"""Compiled checks for C3-S1. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

Every check below runs against delivered bytes and references no unmeasured quantity, except
held_out_bits_per_byte_ramp, which raises ConstantUnmeasured while tests/constants.json carries
nulls. The graded quantity is Held-out bits per byte, b = max(b_P1, b_P2) over two disjoint private shards. Each b is the frozen evaluator total negative log-likelihood in bits over the encoded held-out stream divided by the total raw UTF-8 byte count of the same held-out text. Lower b is better. Because the denominator counts raw corpus bytes and never tokens, a tokenizer that shrinks the token count without predicting better moves b by nothing at all.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SUBMISSION = '/submission/c3s1.json'
CHECKS = []


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "C3-S1: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "submitted_artifact"), "values": kw}

@check(id="bits_per_byte_divides_by_bytes_not_tokens", weight=3, knockout=False, kind="process")
def test_bits_per_byte_divides_by_bytes_not_tokens():
    try:
        accounting = load_submission()["bpb_accounting"]
        bits = float(accounting["nll_bits_total"])
        per_byte = float(accounting["declared_bits_per_byte"])
        byte_total = int(accounting["raw_utf8_byte_total"])
        token_total = int(accounting["token_total"])
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    tolerance = 1e-6 * max(1.0, abs(bits))
    over_bytes = abs(per_byte * byte_total - bits) <= tolerance
    over_tokens = abs(per_byte * token_total - bits) <= tolerance
    # A byte-level tokenizer makes the two totals equal and the distinction
    # undefined, so the byte identity is allowed to stand alone in that one case.
    indistinguishable = byte_total == token_total
    basis = accounting.get("denominator_basis")
    divides_by_bytes = (basis == "raw_utf8_bytes" and over_bytes
                        and (indistinguishable or not over_tokens))
    return divides_by_bytes, evidence(denominator_basis=basis,
                                      byte_total=byte_total,
                                      token_total=token_total,
                                      identity_over_bytes=over_bytes,
                                      identity_over_tokens=over_tokens,
                                      reason=None if divides_by_bytes
                                      else "denominator_is_not_the_byte_total")

@check(id="byte_alphabet_fully_covered", weight=5, knockout=True, kind="process")
def test_byte_alphabet_fully_covered():
    try:
        entries = set(load_submission()["vocabulary"]["entries"])
    except Exception as exc:
        return False, evidence(target="emitted_vocabulary",
                               reason="submission_malformed", error=str(exc))
    uncovered = sorted(BYTE_FALLBACK_ENTRIES - entries)
    return (not uncovered), evidence(target="emitted_vocabulary",
                                     unrepresentable_byte_values=len(uncovered),
                                     first_uncovered=uncovered[:4],
                                     reason=None if not uncovered
                                     else "byte-fallback-incomplete")

@check(id="byte_denominator_is_raw_not_normalised", weight=5, knockout=True, kind="process")
def test_byte_denominator_is_raw_not_normalised():
    try:
        rows = roundtrip_rows()
        declared_total = load_submission()["bpb_accounting"]["raw_utf8_byte_total"]
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    mismeasured, recomputed_total = [], 0
    for row in rows:
        length = len(utf8(row.get("raw_utf8", "")))
        recomputed_total += length
        if row.get("raw_utf8_bytes") != length:
            mismeasured.append(row.get("fixture_class"))
    honest = (not mismeasured) and declared_total == recomputed_total
    return honest, evidence(recomputed_total=recomputed_total,
                            declared_total=declared_total,
                            mismeasured=mismeasured,
                            reason=None if honest
                            else "denominator_not_raw_utf8_bytes")

@check(id="encode_and_train_seconds_declared", weight=3, knockout=False, kind="process")
def test_encode_and_train_seconds_declared():
    declaration = run_record().get("agent_budget_declaration")
    if declaration is None:
        return False, evidence(target="run_record", reason="no_agent_declaration")
    try:
        named = (json.loads(declaration) if isinstance(declaration, str)
                 else dict(declaration))
    except Exception as exc:
        return False, evidence(target="run_record",
                               reason="declaration_unparseable", error=str(exc))
    absent = [key for key in BUDGET_KEYS if key not in named]
    return (not absent), evidence(target="run_record", declared=sorted(named),
                                  absent=absent,
                                  reason=None if not absent
                                  else "declaration_incomplete")

@check(id="frozen_trainer_digest_unchanged", weight=5, knockout=True, kind="process")
def test_frozen_trainer_digest_unchanged():
    record = run_record()
    digests = record.get("frozen_trainer_digests")
    if not isinstance(digests, dict) or "before" not in digests \
            or "after" not in digests:
        return False, evidence(target="run_record", reason="no_digest_record")
    before, after = digests["before"] or {}, digests["after"] or {}
    moved = sorted(k for k in set(before) | set(after)
                   if before.get(k) != after.get(k))
    touched = sorted(record.get("guarded_paths_touched", []))
    intact = (not moved) and (not touched)
    if moved:
        why = "frozen-trainer-modified"
    elif touched:
        why = "grading-tree-write"
    else:
        why = None
    return intact, evidence(target="run_record", files_digested=len(before),
                            moved=moved, touched=touched, reason=why)

@check(id="graded_region_within_wall", weight=3, knockout=False, kind="process")
def test_graded_region_within_wall():
    measured = run_record().get("graded_region_wall_seconds")
    if measured is None:
        return False, evidence(target="run_record", reason="wall_unrecorded")
    try:
        measured = float(measured)
    except Exception as exc:
        return False, evidence(target="run_record", reason="wall_unparseable",
                               error=str(exc))
    inside = measured <= WALL_SECONDS
    return inside, evidence(target="run_record", measured_seconds=measured,
                            wall_seconds=WALL_SECONDS,
                            reason=None if inside else "wallclock-exceeded")

@check(id="held_out_bits_per_byte_ramp", weight=10, knockout=True, kind="process")
def test_held_out_bits_per_byte_ramp():
    # require_measured FIRST, before any read of the submission. Reading the
    # artifact first lets a missing-file error mask the unmeasured signal: the
    # verifier then reports gradeable=true with r_det=0.0, which collapses "not yet
    # measurable" into "the agent scored zero". They are different claims.
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    b = measure()
    # Lower bits per byte is better, so the ramp DESCENDS: floor is the worse end.
    span = c["floor"] - c["knee"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (c["floor"] - b) / span))
    return b <= c["dichotomizing_threshold"], evidence(bits_per_byte=b,
                                                      s_outcome=s)

@check(id="manifest_replay_reproduces_vocabulary_digest", weight=3, knockout=False, kind="process")
def test_manifest_replay_reproduces_vocabulary_digest():
    replayed = run_record().get("manifest_replay_vocabulary_sha256")
    if replayed is None:
        return False, evidence(target="run_record", reason="replay_unavailable")
    try:
        built = load_submission()["vocabulary"]["artifact_sha256"]
    except Exception as exc:
        return False, evidence(target="run_record",
                               reason="submission_malformed", error=str(exc))
    rebuilt = str(replayed) == str(built)
    return rebuilt, evidence(target="run_record", built=built, replayed=replayed,
                             reason=None if rebuilt
                             else "manifest-order-divergence")

@check(id="no_per_shard_breakdown_in_submission", weight=5, knockout=True, kind="process")
def test_no_per_shard_breakdown_in_submission():
    try:
        doc = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    words, numbers = harvest(doc, set(), set())
    named = sorted(w for w in words
                   if any(token in w for token in PRIVATE_SURFACE_TOKENS))
    pinned = sorted(str(name) for name, value in constants().items()
                    if isinstance(value, (int, float))
                    and not isinstance(value, bool) and float(value) in numbers)
    sealed = (not named) and (not pinned)
    return sealed, evidence(private_names=named[:6], pinned_constants=pinned,
                            reason=None if sealed
                            else "private_shard_surface_leaked")

@check(id="roundtrip_covers_adversarial_classes", weight=3, knockout=False, kind="process")
def test_roundtrip_covers_adversarial_classes():
    try:
        rows = roundtrip_rows()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    witnessed = set()
    for row in rows:
        if row.get("raw_utf8"):
            witnessed.add(row.get("fixture_class"))
    uncovered = [name for name in ADVERSARIAL_CLASSES if name not in witnessed]
    return (not uncovered), evidence(
        covered=[n for n in ADVERSARIAL_CLASSES if n in witnessed],
        uncovered=uncovered,
        reason=None if not uncovered else "adversarial_class_unwitnessed")

@check(id="roundtrip_decodes_to_input_bytes", weight=5, knockout=True, kind="process")
def test_roundtrip_decodes_to_input_bytes():
    try:
        rows = roundtrip_rows()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    if not rows:
        return False, evidence(reason="no_roundtrip_evidence")
    lossy = []
    for row in rows:
        if utf8(row.get("decoded_utf8", "")) != utf8(row.get("raw_utf8", "")):
            lossy.append(row.get("fixture_class"))
    return (not lossy), evidence(fixtures_checked=len(rows),
                                 not_byte_identity=lossy,
                                 reason=None if not lossy
                                 else "roundtrip-not-identity")

@check(id="stage_manifest_order_matches_execution", weight=5, knockout=True, kind="process")
def test_stage_manifest_order_matches_execution():
    try:
        stages = list(load_submission()["stage_manifest"])
        declared = [str(stage["stage"]) for stage in stages]
    except Exception as exc:
        return False, evidence(target="stage_manifest",
                               reason="submission_malformed", error=str(exc))
    executed = [str(name) for name in run_record().get("stage_execution_order", [])]
    undigested = [stage.get("stage") for stage in stages
                  if not stage.get("entry_point") or not stage.get("sha256")]
    repeats = len(set(declared)) != len(declared)
    faithful = bool(declared) and declared == executed and not undigested\
        and not repeats
    return faithful, evidence(target="stage_manifest", declared=declared,
                              executed=executed, undigested=undigested,
                              repeated_stage_name=repeats,
                              reason=None if faithful
                              else "manifest-order-divergence")

@check(id="vocabulary_artifact_emitted", weight=5, knockout=True, kind="process")
def test_vocabulary_artifact_emitted():
    if not os.path.exists(SUBMISSION):
        return False, evidence(reason="submission_missing", path=SUBMISSION)
    try:
        doc = load_submission()
    except Exception as exc:
        return False, evidence(reason="submission_malformed", error=str(exc))
    absent = [name for name in SECTIONS if name not in doc]
